import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"11、【泰】 乾下坤上","description":"周易阐真 - 11、【泰】 乾下坤上","frontmatter":{"title":"11、【泰】 乾下坤上","description":"周易阐真 - 11、【泰】 乾下坤上"},"headers":[],"relativePath":"zh/classics/chanzhen/012.md","filePath":"zh/classics/chanzhen/012.md"}'),s={name:"zh/classics/chanzhen/012.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：泰，小往大来。吉，亨。则是天地交而万物通也，上下交而其志同也。内阳而外阴，内健而外顺，内君子而外小人，君子道长，小人道消也。</p></blockquote><h1 id="_11、【泰】-乾下坤上" tabindex="-1">11、【泰】 乾下坤上 <a class="header-anchor" href="#_11、【泰】-乾下坤上" aria-label="Permalink to “11、【泰】 乾下坤上”">​</a></h1><p>初九：拔茅茹，以其汇，征吉。</p><p>九二：包荒，用冯河，不遐遗。朋亡，得尚于中行。</p><p>九三：无平不陂，无往不复。艰贞无咎，勿恤其孚，于食有福。</p><p>六四：翩翩，不富以其邻，不戒以孚。</p><p>六五：帝乙归妹，以祉元吉。</p><p>上六：城复于隍。勿用师。自邑告命，贞吝。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：天地交，泰。后以财成天地之道，辅相天地之宜，以左右民。</p><p>财同裁。相音象。左音佐。右音佑。</p><p>泰者，通也。上坤地，下乾天，天气自下而上升，地气自上而下降，是天地阴阳之气相交，万物发生，泰之象也。</p><p>元后有见于此，知天地阴阳相交而万物生，人之阴阳相交而万化安，以之财成天地之道，辅相天地之宜焉。人秉天地阴阳五行之气而生身，身中即具此阴阳五行之气。此气在人身中，发而为五德。五德其体，有自然之道，不待勉强，所谓率性之道也。后明五行相生之理，使仁义理智信一气流行，裁成乎天地生人自然之道。五德其用，有当然之宜，不可偏执，所谓修道之教也。后明五行相克之理，使仁义礼智信各得其当，辅相其天地赋人当然之宜。裁成其道，辅相其宜，凡以为通天下之志，成天下之务，以左右斯民，使人人皆以天地之道为道，以天地之宜为宜，保合太和，各正性命耳。噫!谁无天地之道?谁无天地之宜?特患不能裁成，不能辅相耳。果能裁成之，则先天可全；果能辅相之，则后天可化。先天全，后天化，其体自然，其用当然，五行一气，五德混成，性命凝结，方且与天地同功用，与天地同长久，其泰为何如哉！</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>汇，音胃。冯，音冯副本。</p><p>泰者，通和之义。卦德上坤顺，下乾健，阳健于内，阴顺于外，健顺如一，阴阳相应，故谓泰。此阴阳相交之卦，承上小畜而来。小畜一阴，而畜五阳，阴气主事，阳气不振，小于畜而不能大于畜，其行不通。通行之道，必须大小无伤，阴阳相当，阴顺阳而阳统阴，阴阳和合，方能济事。故泰之为道，小往大来，吉而得亨也。</p><p>小者阴也，大者阳也。小往则阴顺，大来则阳健。阳健于内，阴顺于外，先天渐复，后天渐化，可以造于纯阳无阴之地。于理得吉，于行行亨，但致泰之道，有火候、有工程，进之退之，各有其时。不失其时，健而顺行，以顺养健，未泰者而能致，已泰者而能保，由了命而了性，自有为而无为，完成大道，理有可决也。</p><p>初九，一阳潜生，诸阳皆有动机，如拔茅之茹根以及汇叶也。致泰者，乘此一阳发现，而即下手修为，渐采渐炼，由微而著，未有阳不健而阴不顺者，故曰“征吉”。此刚而乘时以致泰也。</p><p>九二，刚健中正，通权达变，是以包荒用冯河，不遐遗朋亡也。包荒者，度量宽宏，用柔也。冯河者，志气勇敢，用刚也。不遐遗者，静观密察，柔之至。朋亡者，闲邪存诚，刚之至。刚中有柔，柔中有刚，文烹武炼，左之右之，无不宜之，得尚于中行矣。此刚柔相济以致泰也。</p><p>九三，三阳已足，阳极必阴，泰极必否，如无平不陂，无往不复。当此之时，须要知进知退，艰难守贞，防危虑险，方无得而复失之咎。既无其咎，功成人间，名标天上，且食天福，享寿无穷，何忧恤之有？此刚极守正以保泰也。</p><p>六四，当阳极交阴之际，不能防危虑险，一阴潜生，群阴皆动，如翩翩不富以其邻，无待相戒而孚合，金丹已得而复失。此以柔伤刚而失泰也。</p><p>六五，当正泰之时，以阴养阳，阳气凝结，如帝乙归妹，以祉及于臣下，阴恋阳而阳恋阴，阴阳同气，自有天然真火，炉中赫赫长红，虽在已泰而不失初泰之吉。此以柔养刚而全泰也。</p><p>上六，在泰之终，顺之极，只知泰之顺，不知泰之逆，不防于早，必败于终，如城倾而复于隍矣。当此之时，好事已去，难以为力，故曰“勿用行师”。凶事已临，后悔不及，故曰“自邑告命，贞吝”。此柔而不知早于保泰也。</p><p>然则致泰保泰，各有其时；有为无为，各有其法。随时而行，依法而作，健所当健，顺所当顺，健以致泰，顺以保泰，未泰者能泰，已泰者长泰，何患不吉不亨，大道不成乎！</p>',24)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
